"use client";

import React, { useState } from "react";
import { AppWindow, Star, ArrowRight } from "lucide-react";

export function MobileAppInstallBanner() {
  const [active, setActive] = useState(true);

  if (!active) return null;

  return (
    <div className="w-full max-w-2xl bg-card/45 backdrop-blur-xl border border-border/50 p-4 rounded-xl shadow-lg select-none font-sans text-foreground flex flex-col sm:flex-row items-center justify-between gap-3 relative overflow-hidden">
      <div className="absolute inset-0 bg-gradient-to-r from-violet-500/10 via-transparent to-transparent pointer-events-none" />

      <div className="flex items-center gap-2.5 relative z-10">
        <div className="p-2 rounded-lg bg-violet-500/15 border border-violet-500/20 text-violet-400">
          <AppWindow className="w-4 h-4" />
        </div>
        <div className="text-xs">
          <h4 className="font-black leading-none mb-1 text-violet-300">Download Mobile app</h4>
          <div className="flex items-center gap-2 text-[10px] text-muted-foreground/60">
            <span className="flex items-center gap-0.5"><Star className="w-3 h-3 fill-yellow-400 text-yellow-400" /> 4.9</span>
            <span>•</span>
            <span>Scan QR Code to install</span>
          </div>
        </div>
      </div>

      <button className="px-3.5 py-1.5 bg-primary hover:brightness-110 text-white text-[10px] font-extrabold rounded-lg flex items-center gap-1 transition-all relative z-10">
        <span>Install PWA App</span>
        <ArrowRight className="w-3 h-3" />
      </button>
    </div>
  );
}
